<script setup lang="ts">
import { lessons } from '../data/content'
import { computed, ref } from 'vue'
import { useLearning } from '../stores/learning'
import { createBackup, parseBackup } from '../data/backup'
import type { LearningState } from '../data/state'
import { canInstall, installApp, offlineReady } from '../lib/pwa'
import { isCompleted } from '../lib/progress'
import AppIcon from '../components/AppIcon.vue'
const store=useLearning()
const name=ref(store.state.settings.name),dailyMinutes=ref(store.state.settings.dailyMinutes),prayerEnabled=ref(store.state.settings.prayerEnabled)
const message=ref(''),importError=ref(''),imported=ref<LearningState|null>(null),busy=ref(false)
const importSummary=computed(()=>imported.value?{completed:Object.values(imported.value.progress).filter(isCompleted).length,notes:Object.values(imported.value.notes).filter(Boolean).length,questions:imported.value.questions.length}:null)
async function save(){store.updateSettings({name:name.value.trim(),dailyMinutes:dailyMinutes.value,prayerEnabled:prayerEnabled.value});await store.persist();message.value=store.error?'Pengaturan belum tersimpan.':'Pengaturan tersimpan.'}
async function exportData(){
 await store.persist()
 const blob=new Blob([JSON.stringify(createBackup(store.state),null,2)],{type:'application/json'})
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`belajar-islam-${store.todayKey}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='Cadangan JSON sudah disiapkan untuk diunduh.'
}
async function pickFile(event:Event){
 imported.value=null;importError.value='';const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return
 try{if(file.size>5*1024*1024)throw new Error('Berkas melebihi batas 5 MB.');imported.value=parseBackup(await file.text())}catch(error){importError.value=error instanceof Error?error.message:'Berkas belum dapat dibaca.'}finally{input.value=''}
}
async function applyImport(){if(!imported.value)return;busy.value=true;try{await store.replaceState(imported.value);name.value=store.state.settings.name;dailyMinutes.value=store.state.settings.dailyMinutes;prayerEnabled.value=store.state.settings.prayerEnabled;imported.value=null;message.value='Progres berhasil diimpor.'}catch{importError.value='Impor belum berhasil. Data sebelumnya tetap dipertahankan.'}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">SESUAIKAN DENGAN RITMEMU</p><h1>Pengaturan</h1><p>Ruang ini milikmu. Pilih yang membantu perjalananmu.</p></div></div><div class="settings-layout"><section class="card"><h2>Belajar dengan ritmemu</h2><form @submit.prevent="save"><label for="user-name" class="field-label">Nama panggilan (opsional)</label><input id="user-name" v-model="name" class="form-input" maxlength="60" placeholder="Bagaimana kami menyapamu?" autocomplete="given-name"/><label for="daily-minutes" class="field-label">Target menit belajar per hari</label><select id="daily-minutes" v-model.number="dailyMinutes" class="form-input"><option v-for="n in [5,10,15,20,30]" :key="n" :value="n">{{n}} menit</option><option v-if="![5,10,15,20,30].includes(dailyMinutes)" :value="dailyMinutes">{{dailyMinutes}} menit</option></select><p class="small-note">Target adalah pengingat lembut, bukan kewajiban atau penilaian.</p><label class="check-row settings-check"><input v-model="prayerEnabled" type="checkbox"/><span><strong>Aktifkan pencatat shalat harian</strong><br/><span class="muted">Catatan pribadi untuk lima waktu. Opsional dan tanpa skor.</span></span></label><button type="submit" class="button primary mt-4">Simpan pengaturan</button></form></section><section class="card"><h2>Cadangan progres</h2><p class="muted text-sm mt-3">Progres, hafalan, favorit, catatan, dan pertanyaan tersimpan hanya di browser ini. Ekspor secara berkala; data tidak disinkronkan antar perangkat.</p><div class="button-row"><button class="button primary" @click="exportData"><AppIcon name="download" :size="16"/>Ekspor JSON</button><label class="button secondary file-button" for="import-file"><AppIcon name="upload" :size="16"/>Pilih JSON untuk impor<input id="import-file" type="file" accept=".json,application/json" class="file-input" @change="pickFile"/></label></div><p class="small-note">Versi cadangan 1 · Maksimal 5 MB. Menghapus data situs atau memakai mode privat dapat menghilangkan progres. Berkas ekspor memuat catatan pribadimu.</p><div v-if="imported && importSummary" class="import-preview callout"><h3>Periksa cadangan sebelum impor</h3><p>{{importSummary.completed}} pelajaran selesai · {{importSummary.notes}} catatan · {{importSummary.questions}} pertanyaan.</p><p><strong>Impor akan mengganti seluruh data lokal saat ini.</strong> Ekspor data sekarang jika ingin menyimpannya.</p><div class="button-row"><button class="button primary" :disabled="busy" @click="applyImport">{{busy?'Mengimpor…':'Impor dan ganti progres'}}</button><button class="button secondary" :disabled="busy" @click="imported=null">Batal</button></div></div><p v-if="importError" class="inline-error" role="alert">{{importError}}</p></section><section class="card"><h2>Belajar tanpa koneksi</h2><p class="muted text-sm mt-3">Pelajaran, font, dan audio basmalah disimpan untuk offline setelah pemuatan pertama selesai. Tautan sumber tetap memerlukan internet.</p><button v-if="canInstall" class="button primary mt-4" @click="installApp"><AppIcon name="download" :size="16"/>Pasang aplikasi</button><p v-else class="small-note">Untuk memasang, buka menu browser → “Instal aplikasi” atau “Tambahkan ke layar utama”. Pada iPhone/iPad, gunakan menu Bagikan di Safari.</p><p class="small-note">{{offlineReady?'Materi siap digunakan offline di perangkat ini.':'Buka sekali saat terhubung dan tunggu materi selesai disimpan. Status offline muncul ketika service worker siap.'}}</p></section><section class="card"><h2>Tentang materi</h2><p class="muted text-sm mt-3">{{lessons.length}} pelajaran dari {{store.totalPlanned}} topik rencana tersedia. Semua materi contoh, teks Arab, dan transliterasi masih perlu ditinjau guru. Sumber dicantumkan per pelajaran. Untuk perbedaan pendapat antar mazhab dan persoalan pribadi, tanyakan kepada guru.</p></section></div><p v-if="message" class="save-message" role="status">{{message}}</p></template>
